/// The gallery's example of `ValueSlider`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_step = args.number("step") as f32;
        let arg_unit = args.text("unit");
        let arg_label = args.text("label");
        let arg_show_label = args.bool("show_label");
        let arg_disabled = args.bool("disabled");
        let arg_field = args.bool("field");

        let (opacity, size) = (State::new(80.0_f32), State::new(24.0_f32));
        HStack::new((
            {
                let mut it = ValueSlider::new(opacity.binding()).range(0.0, 100.0);
                it = it.step(arg_step);
                it = it.unit(arg_unit.clone());
                it = it.label(arg_label.clone());
                if arg_show_label {
                    it = it.show_label();
                }
                it = it.disabled(arg_disabled);
                if arg_field {
                    it = it.field();
                }
                it
            },
            ValueSlider::new(size.binding()).range(1.0, 200.0).step(1.0).unit(" px").label("Size").field(),
        ))
        .spacing(24.0)
        .align(Align::Center)
    })
}

